<section class="workspace-card mb-4"><div class="panel-body pb-0"><div class="table-toolbar"><div class="search-input"><i class="bi bi-search"></i><input class="form-control" placeholder="Cari nama atau nomor peserta…" aria-label="Cari peserta" x-model="search" @input="pageNumber=1"></div><select class="form-select" aria-label="Filter status" x-model="statusFilter" @change="pageNumber=1"><option value="">Semua status</option><template x-for="status in ['belum_ada','draf','terkirim','diverifikasi','perbaikan','diterima_lengkap']"><option :value="status" x-text="label(status)"></option></template></select><?php if ($role === 'admin'): ?><select class="form-select" aria-label="Filter operator" x-model="operatorFilter" @change="pageNumber=1"><option value="">Semua operator</option><?php for($i=1;$i<=4;$i++): ?><option value="<?= $i ?>">Operator <?= $i ?></option><?php endfor ?></select><button class="btn btn-light border" @click="downloadCsv()" title="Ekspor contoh CSV" aria-label="Ekspor contoh CSV"><i class="bi bi-download"></i></button><?php endif ?></div></div><div class="table-responsive"><table class="table portal-table"><thead><tr><th>Peserta / nomor SK</th><th>Jalur akses</th><th>Status pendaftaran</th><th>WhatsApp</th><?php if ($role === 'admin'): ?><th>Operator</th><?php endif ?><th class="text-end">Tindak lanjut</th></tr></thead><tbody><template x-for="row in pagedRows" :key="row.id"><tr><td><div class="table-person"><span class="avatar-mini" x-text="row.name.charAt(0)"></span><div><strong x-text="row.name"></strong><small x-text="row.number"></small></div></div></td><td><i class="bi me-1" :class="row.path === 'Google' ? 'bi-google text-purple' : 'bi-whatsapp text-success'"></i><span x-text="row.path"></span></td><td><span class="status-pill" :class="row.status" x-text="label(row.status)"></span></td><td><span class="small" :class="row.wa ? 'text-success' : 'text-muted'"><i class="bi me-1" :class="row.wa ? 'bi-check-circle' : 'bi-clock'"></i><span x-text="row.wa ? 'Terverifikasi' : 'Belum diperiksa'"></span></span></td><?php if ($role === 'admin'): ?><td x-text="'Operator '+row.operator"></td><?php endif ?><td class="text-end"><a :href="detailUrl(row.id)" class="table-action">Periksa <i class="bi bi-arrow-right"></i></a></td></tr></template></tbody></table><div class="empty-state compact" x-show="!filteredRows.length"><i class="bi bi-search"></i><h3>Peserta tidak ditemukan</h3><p>Coba nama lain atau ubah filter pencarian.</p><button class="btn btn-sm btn-outline-purple" @click="search=''; statusFilter=''; operatorFilter=''; pageNumber=1">Hapus filter</button></div></div><div class="table-pagination"><span x-text="filteredRows.length ? 'Menampilkan '+((pageNumber-1)*pageSize+1)+'–'+Math.min(pageNumber*pageSize,filteredRows.length)+' dari '+filteredRows.length+' peserta contoh' : '0 peserta'"></span><div class="d-flex align-items-center gap-2"><button class="btn btn-sm btn-light border" @click="pageNumber--" :disabled="pageNumber <= 1" aria-label="Halaman sebelumnya"><i class="bi bi-chevron-left"></i></button><span x-text="pageNumber+' / '+totalPages"></span><button class="btn btn-sm btn-light border" @click="pageNumber++" :disabled="pageNumber >= totalPages" aria-label="Halaman berikutnya"><i class="bi bi-chevron-right"></i></button></div></div></section>
